// Legacy route: /cms/dashboard → /dashboard
// Kept so existing bookmarks and the login redirect don't break.

import React, { useEffect } from "react";
import { navigate } from "gatsby";

const CmsDashboardRedirect: React.FC = () => {
  useEffect(() => {
    navigate("/dashboard", { replace: true });
  }, []);
  return null;
};

export default CmsDashboardRedirect;
